  array (
    'symbol' => 'K',
    'name' => 'Potassium',
    'atomic' => 19,
    'category' => 'alkali metal',
    'description' => '',
    'extract_html' => '<p><a href="/school1/ptable/element/K" class="wiki-link" title="Potassium (K)"><a href="/school1/ptable/element/K" class="wiki-link" title="Potassium (K)">Potassium</a></a> (symbol K, derived from Neo-Latin <i>kalium</i>, atomic number 19) is a soft, silvery-white alkali metal that is essential for life on Earth. So soft that it can easily be cut with a butter knife, <a href="/school1/ptable/element/K" class="wiki-link" title="Potassium (K)">potassium</a> reacts violently with water, bursting into a striking lilac flame. It is the seventh most abundant element in Earth\'s crust and serves as the primary electrolyte inside living cells, powering nerve signals, muscle contractions, and heart rhythms across the biological world.</p>',
    'local_image' => 'https://upload.wikimedia.org/wikipedia/commons/b/b3/Potassium.JPG',
    'atomic_mass' => 39.09831,
    'density' => 0.862,
    'melt' => 336.7,
    'boil' => 1032,
