    'melt' => 2896,
    'boil' => 4912,
    'phase' => 'Solid',
    'discovered_by' => 'Carl Wilhelm Scheele',
    'electron_configuration' => '1s2 2s2 2p6 3s2 3p6 4s2 3d10 4p6 5s1 4d5',
    'electronegativity_pauling' => 2.16,
    'electron_affinity' => 72.1,
    'ionization_energies' => 
